'use client';
import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { useRouter } from 'next/navigation';
import { isSteamID64, extractSteamID } from '../utils/steamUtils';

interface SteamProfileSearchProps {
  onProfileFound?: (steamId: string) => void;
  className?: string;
}

export default function SteamProfileSearch({ onProfileFound, className = '' }: SteamProfileSearchProps) {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const router = useRouter();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);

    try {
      let steamId = '';
      
      // Verificar si es un SteamID64 o contiene uno
      const extractedId = extractSteamID(input);
      if (extractedId) {
        steamId = extractedId;
      } else {
        // Si no es un SteamID64, intentar resolver como vanityURL
        const response = await fetch(`/api/resolveVanityURL?vanityurl=${encodeURIComponent(input)}`);
        if (!response.ok) {
          throw new Error('No se pudo resolver el perfil de Steam');
        }
        const data = await response.json();
        steamId = data.steamid;
      }

      if (!steamId) {
        throw new Error('No se pudo encontrar un ID de Steam válido');
      }

      // Llamar al callback si existe
      if (onProfileFound) {
        onProfileFound(steamId);
      } else {
        // Si no hay callback, redirigir a una página de perfil
        router.push(`/profile/${steamId}`);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Error al buscar el perfil');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <motion.div 
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.3 }}
      className={`w-full max-w-md mx-auto ${className}`}
    >
      <form onSubmit={handleSubmit} className="flex flex-col gap-2">
        <div className="flex">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="URL de perfil, SteamID64 o nombre personalizado"
            className="flex-1 px-4 py-2 border border-gray-300 rounded-l-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            disabled={isLoading}
          />
          <button
            type="submit"
            disabled={isLoading || !input.trim()}
            className="bg-blue-600 text-white px-4 py-2 rounded-r-lg hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 disabled:opacity-50"
          >
            {isLoading ? 'Buscando...' : 'Buscar'}
          </button>
        </div>
        
        {error && (
          <motion.p
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="text-red-500 text-sm mt-1"
          >
            {error}
          </motion.p>
        )}
        
        <p className="text-xs text-gray-500 mt-1">
          Ingresa un perfil de Steam: URL completa, SteamID64 o nombre personalizado
        </p>
      </form>
    </motion.div>
  );
}